const visits=(demo?demoVisits:savedVisits).filter(v=>v&&v.iso&&v.city).map(enrichStadium).map(v=>v.iso.toUpperCase()==='ARG'&&['avellaneda','avellaneda buenos aires'].includes(norm(v.city).replace(/[^a-z ]/g,'').trim())?{...v,city:'Buenos Aires',atlasLocality:v.city}:v);
const demoFlights={flights:[{id:'ex-1',origin:'GRU',destination:'MAD',carrier:'Iberia',year:2024,dayMonth:'25/10'},{id:'ex-2',origin:'MAD',destination:'NCE',carrier:'Iberia',year:2024,dayMonth:'27/10'},{id:'ex-3',origin:'NCE',destination:'MAD',carrier:'Iberia',year:2024,dayMonth:'31/10'},{id:'ex-4',origin:'MAD',destination:'GRU',carrier:'Iberia',year:2024,dayMonth:'05/11'},{id:'ex-5',origin:'GRU',destination:'ISL',carrier:'Turkish Airlines',year:2011},{id:'ex-6',origin:'ISL',destination:'NRT',carrier:'Turkish Airlines',year:2011},{id:'ex-7',origin:'GRU',destination:'MEX',carrier:'LATAM',year:2026}],trips:[{id:'ex-trip-1',name:'Nice via Madrid · exemplo',flightIds:['ex-1','ex-2','ex-3','ex-4']},{id:'ex-trip-2',name:'Tóquio via Istambul · exemplo',flightIds:['ex-5','ex-6']},{id:'ex-trip-3',name:'Cidade do México · exemplo',flightIds:['ex-7']}]};
let aviation;try{aviation=aviationValidate(savedFlights||(demo?demoFlights:{flights:[],trips:[]}))}catch{aviation=aviationValidate(demoFlights)}
const countries=[...new Map(visits.map(v=>[v.iso.toUpperCase(),{iso:v.iso.toUpperCase(),name:v.country}])).values()].sort((a,b)=>a.name.localeCompare(b.name,'pt'));
const cities=new Set(visits.map(v=>v.iso+'|'+norm(v.city))),stadiums=visits.filter(v=>v.stadium),stadiumCount=new Set(stadiums.map(v=>v.iso+'|'+norm(v.stadium))).size;
const routeFlights=aviation.flights.filter(aviationHasRoute);
const carriers=[...new Set(aviation.flights.map(f=>f.carrier).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt'));
const carrierIcon=c=>{const n=norm(c);return n.includes('copa')?'copaairlines':n.includes('british')?'britishairways':n.includes('turkish')?'turkishairlines':n.includes('avianca')?'avianca':n.includes('iberia')?'iberia':n.includes('jetblue')?'jetblue':n.includes('lufthansa')?'lufthansa':null};
const credit=k=>`<a class="photo-credit" href="${photoCredits[k].source}" target="_blank" rel="noopener noreferrer">Foto: ${esc(photoCredits[k].author)} · ${photoCredits[k].license} ↗</a>`;
function stats(){return `<section class="preview-stats" aria-label="Resumo do seu Atlas">${[['globe',countries.length,'países visitados','countries'],['pin',cities.size,'cidades exploradas','cities'],['stadium',stadiumCount,'estádios na memória','stadiums'],['plane',aviation.flights.length,'voos registrados','flights']].map(([i,n,label,topic])=>`<a class="stat-topic" href="${topic==='stadiums'?'#stadiums':'#'+topic}" data-topic="${topic}" aria-label="Explorar ${num(n)} ${label}">${icon(i)}<strong>${num(n)}</strong><span>${label}</span><i aria-hidden="true">${icon('arrow')}</i></a>`).join('')}</section>`}
const nav=`<header class="preview-header"><a class="wordmark" href="#main">${icon('globe')}<span>Meu Atlas<span class="wordmark-sub">VIAGENS & FUTEBOL</span></span><i></i></a><nav class="main-nav" aria-label="Navegação do Atlas"><a href="#explore">Explorar o mundo</a><a href="#stadiums" class="stadiums-nav">Estádios</a><a href="#journeys">Minhas viagens</a><a href="#memories">Memórias</a></nav><button class="back-atlas manager-entry" data-manage="stadiums">Gerenciar meu Atlas ${icon('arrow')}</button></header>`;
const competitions=[{"id":"paulista","name":"Campeonato Paulista"},{"id":"copa-do-brasil","name":"Copa do Brasil"},{"id":"brasileirao","name":"Brasileirão"},{"id":"copinha","name":"Taça São Paulo"},{"id":"libertadores","name":"CONMEBOL Libertadores"},{"id":"sudamericana","name":"CONMEBOL Sudamericana"},{"id":"recopa","name":"CONMEBOL Recopa"},{"id":"libertadores-feminina","name":"CONMEBOL Libertadores Feminina"},{"id":"olimpiadas","name":"Olimpíadas"},{"id":"champions-league","name":"UEFA Champions League"},{"id":"la-liga","name":"La Liga"},{"id":"copa-do-mundo","name":"Copa do Mundo FIFA"},{"id":"copa-do-nordeste","name":"Copa do Nordeste"},{"id":"liga-mx","name":"Liga Mexicana"}];
function passport(){return `<section class="passport-strip"><div class="strip-heading"><span class="eyebrow">CARIMBOS NO PASSAPORTE</span><span class="rail-tools"><span>Arraste para explorar</span><button id="railMotion" aria-pressed="false">Pausar movimento</button></span></div><div class="flag-track auto-rail" tabindex="0" role="region" aria-label="Países visitados; arraste ou use as setas para navegar">${countries.map(c=>`<button class="flag-item" data-country="${c.iso}" title="Explorar ${esc(c.name)}">${countryCodes[c.iso]?`<img src="assets/flags/${countryCodes[c.iso]}.svg" width="32" height="24" alt="">`:icon('globe')}<span>${esc(c.name)}</span></button>`).join('')}</div><div class="carrier-row"><span>QUEM ME LEVOU</span><div class="auto-rail" tabindex="0" role="region" aria-label="Companhias aéreas; arraste ou use as setas para navegar">${carriers.map(c=>`<span class="carrier-wordmark">${carrierIcon(c)?`<img src="assets/airlines/${carrierIcon(c)}.svg" width="27" height="27" alt="">`:icon('plane')}<b>${esc(c)}</b></span>`).join('')}</div></div><div class="competition-row"><span>COMPETIÇÕES<br>QUE VIVI</span><div class="competition-track auto-rail" tabindex="0" role="region" aria-label="Competições que assisti; arraste ou use as setas para navegar">${competitions.map(c=>`<span class="competition-wordmark" title="${esc(c.name)}"><img src="assets/competitions/${c.id}.webp" width="130" height="58" alt="" loading="lazy" decoding="async"><span>${esc(c.name)}</span></span>`).join('')}</div></div></section>`}
const tripOptions=()=>aviation.trips.map(t=>`<option value="${esc(t.id)}">${esc(t.name)}</option>`).join('');
const mapMarkup=`<section class="explore-panel" id="explore" aria-labelledby="mapTitle"><div class="explore-heading"><div><span class="eyebrow">SEU MUNDO, EM MOVIMENTO</span><h2 id="mapTitle">Cada rota tem uma história.</h2></div><div class="map-switch" role="group" aria-label="Visualização do mapa"><button data-view="3d" aria-pressed="false">Globo 3D</button><button data-view="2d" aria-pressed="true">Mapa 2D</button></div></div><div class="map-toolbar"><label class="trip-picker">${icon('plane')}<span class="sr-only">Selecionar viagem</span><select id="tripSelect"><option value="">Todas as minhas rotas</option>${tripOptions()}</select></label><button class="map-reset" id="resetView" aria-label="Retornar à visão global">${icon('globe')} Visão global</button></div><div class="map-layer-controls" role="group" aria-label="Conteúdo do mapa"><button data-layer="stadiums" aria-pressed="false">Estádios</button><button data-layer="flights" aria-pressed="false">Voos</button><button data-layer="all" aria-pressed="true">Tudo</button></div><div class="map-stage"><div id="previewMap2d" role="region" aria-label="Mapa bidimensional das viagens"></div><div id="previewGlobe" role="region" aria-label="Globo tridimensional das viagens" hidden></div><p class="globe-loading" id="globeLoading" role="status" hidden>Preparando seu mundo…</p><div class="map-floating-caption"><span class="live-dot"></span><span id="mapCaption">Suas rotas e memórias</span></div><div class="playback"><button id="playJourney">${icon('play')} Reproduzir viagem</button><span id="playLabel" aria-live="polite">Selecione uma viagem para acompanhar</span></div><div class="map-place" id="mapPlace" hidden><button id="closePlace" aria-label="Fechar detalhes">×</button><span class="eyebrow" id="placeKind"></span><h3 id="placeTitle"></h3><p id="placeDescription"></p><button id="placeExplore">Ver no meu Atlas ${icon('arrow')}</button></div></div><div class="map-bottom"><span><i></i>Destinos e estádios</span><span>Arraste para explorar · clique nos pontos</span><span id="animationNote">Trajetos ilustrativos</span></div></section>`;
function memories(){return `<section class="memories-section" id="memories"><div class="section-title"><div><span class="eyebrow">LUGARES QUE FICAM</span><h2>O destino é só o começo.</h2></div><a href="#stadiums">Minha coleção de estádios ${icon('arrow')}</a></div><div class="destination-cards">${[['mexico','Cidade do México','Entre a cidade e a arquibancada.'],['istanbul','Istambul','Onde continentes se encontram.'],['tokyo','Tóquio','Outro fuso. Novas perspectivas.']].map(([id,name,line],i)=>`<article class="destination-card"><button class="destination-image" data-destination="${['MEX','TUR','JPN'][i]}" aria-label="Explorar ${name}"><img src="assets/editorial/${id}.webp" alt="Panorama de ${name}" loading="lazy" width="1920" height="${id==='tokyo'?1080:1440}"><span>${String(i+1).padStart(2,'0')} / MEMÓRIAS</span>${icon('arrow')}</button><div><h3>${name}</h3><p>${line}</p>${credit(id)}</div></article>`).join('')}</div></section>`}
let selectedFlight=null;
const flightState={q:'',carrier:'',bridge:false,year:'',limit:20,type:'',scope:'all',country:'',origin:'',destination:'',sort:'newest',listOpen:false,pane:null,cityKey:''};
const isBridge=f=>(['CGH','GRU'].includes(f.origin)&&['SDU','GIG'].includes(f.destination))||(['SDU','GIG'].includes(f.origin)&&['CGH','GRU'].includes(f.destination));
const airlineKey=c=>{const n=norm(c).trim();return /latam|^tam$/.test(n)?'LATAM':/^gol\b/.test(n)?'GOL':c||'Não informada'};
const flightDate=f=>f.dayMonth?aviationDateLabel(f):f.year?String(f.year)+(f.yearStatus==='estimated'?' · ano estimado':''):f.dateNote||'Data não informada';
const durationLabel=f=>{const m=aviationDuration(f);return m===null?'Duração não disponível':`${Math.floor(m/60)}h ${String(m%60).padStart(2,'0')}min${f.minutes>0&&!/estim/i.test(f.minutesKind)?'':' · estimada'}`};
function recent(){const durations=aviation.flights.map(aviationDuration),total=durations.reduce((s,n)=>s+(n||0),0),estimated=aviation.flights.some(f=>aviationDuration(f)!==null&&(!(f.minutes>0)||/estim/i.test(f.minutesKind)));const indicators=[['all',aviation.flights.length,'Total de voos','Todos os trechos registrados'],['international',aviation.flights.filter(f=>flightCategory(f)==='international').length,'Voos internacionais','Entre países diferentes · ida e volta'],['bridge',aviation.flights.filter(isBridge).length,'São Paulo ↔ Rio','CGH / GRU ↔ SDU / GIG'],['hours',total?num(total/60)+'h':'—','Horas de voo',`${estimated?'Inclui durações estimadas':'Durações registradas'} · ${durations.filter(n=>n!==null).length} de ${aviation.flights.length} voos`]];return `<section class="journeys-section" id="journeys"><div class="section-title"><div><span class="eyebrow">MINHA HISTÓRIA NOS CÉUS</span><h2>Cada voo, um novo destino.</h2><p>Companhias, percursos e tempo pelo mundo.</p></div><div class="manager-section-actions"><button class="manager-section-button" data-manager-new="flight">＋ Incluir voo</button><button class="manager-section-button" data-manage="flights">Gerenciar voos</button><button class="manager-section-button" data-manage="trips">Organizar viagens</button></div></div><div class="flight-indicators">${indicators.map(([key,value,label,note])=>`<button class="flight-indicator" data-flight-filter="${key}" aria-controls="flightCollection">${icon('plane')}<strong>${value}</strong><span>${label}</span><small>${note}</small>${icon('arrow')}</button>`).join('')}</div><button class="gold-button flight-explore" id="flightExplore" aria-expanded="false" aria-controls="flightCollection">Explorar meus voos ${icon('arrow')}</button><div id="flightCollection" hidden><div class="section-title"><div><span class="eyebrow">COLEÇÃO DE VOOS</span><h3>De onde parti. Onde cheguei.</h3></div></div><div class="flight-filters unified-flight-filters" id="flightFilters" role="group" aria-label="Filtros combinados de voos"></div><button class="outline-button flight-csv-export" data-export-flight-csv>Exportar recorte de voos · CSV</button><p class="flight-results" id="flightCount" role="status" aria-live="polite"></p><div class="flight-grid" id="flightGrid"></div><div class="stadium-more"><button class="outline-button" id="flightMore">Carregar mais voos</button><span id="flightShown"></span></div></div></section>`}
function renderFlightList(){const fs=filteredFlightRows();$('#flightCount').textContent=`${fs.length} ${fs.length===1?'voo encontrado':'voos encontrados'}${flightState.bridge?' · São Paulo ↔ Rio':''}`;$('#flightGrid').innerHTML=fs.slice(0,flightState.limit).map(f=>`<article class="flight-card"><span class="flight-carrier">${esc(f.carrier||'Companhia não informada')}</span><div class="flight-route"><strong>${esc(f.origin||'—')}</strong>${icon('plane')}<strong>${esc(f.destination||'—')}</strong></div><p class="flight-cities">${esc(f.originCity||'Origem não informada')} → ${esc(f.destinationCity||'Destino não informado')}</p><div class="flight-card-meta"><span>${esc(flightDate(f))}</span><span>${esc(durationLabel(f))}</span></div><div class="flight-card-actions"><button data-flight-detail="${esc(f.id)}">Detalhes ${icon('arrow')}</button>${aviationHasRoute(f)?`<button data-flight-map="${esc(f.id)}" aria-label="Ver rota ${esc(f.origin)} para ${esc(f.destination)} no mapa">${icon('pin')}</button>`:''}</div></article>`).join('')||'<p class="gallery-empty">Nenhum voo para estes filtros. Tente outra busca.</p>';$('#flightMore').hidden=fs.length<=flightState.limit;$('#flightShown').textContent=`${Math.min(fs.length,flightState.limit)} de ${fs.length} voos`}
const flightCountry=(f,side)=>{const value=aviationAirport(f[side])?.country||f[side+'Country']||'';return value.trim()};
const countryKey=c=>['brasil','brazil','bra','br'].includes(norm(c))?'brasil':norm(c);
function flightCategory(f){const a=countryKey(flightCountry(f,'origin')),b=countryKey(flightCountry(f,'destination'));if(!a||!b)return 'unknown';return a==='brasil'&&b==='brasil'?'domestic':a!==b?'international':'foreignDomestic'}
function flightMatchesAdvanced(f){const a=countryKey(flightCountry(f,'origin')),b=countryKey(flightCountry(f,'destination'));return (!flightState.type||flightCategory(f)===flightState.type)&&(!flightState.country||b===flightState.country)&&(!flightState.origin||f.origin===flightState.origin)&&(!flightState.destination||f.destination===flightState.destination)&&(flightState.type!=='international'||flightState.scope==='all'||(flightState.scope==='outbound'?a==='brasil':flightState.scope==='inbound'?b==='brasil':a!=='brasil'&&b!=='brasil'))}
function filteredFlightRows(){const q=norm(flightState.q);return aviation.flights.filter(f=>(!flightState.carrier||airlineKey(f.carrier)===flightState.carrier)&&(!flightState.bridge||isBridge(f))&&(!flightState.year||(flightState.year==='unknown'?!f.year:String(f.year)===flightState.year))&&q.split(/\s+/).every(term=>norm([f.origin,f.destination,f.originCity,f.destinationCity,f.originCountry,f.destinationCountry,f.carrier,f.code,f.year].join(' ')).includes(term))&&flightMatchesAdvanced(f)&&(!flightState.cityKey||countryKey(flightCountry(f,'destination'))+'|'+norm(f.destinationCity)===flightState.cityKey)).sort((a,b)=>{if(flightState.sort==='route')return (a.origin+' '+a.destination).localeCompare(b.origin+' '+b.destination);if(!a.year||!b.year)return a.year?-1:b.year?1:0;const diff=a.year-b.year;if(diff)return flightState.sort==='oldest'?diff:-diff;const date=f=>f.dayMonth?Number(f.dayMonth.slice(3))*32+Number(f.dayMonth.slice(0,2)):null;const da=date(a),db=date(b);if(da===null||db===null)return da===null?(db===null?0:1):-1;return flightState.sort==='oldest'?da-db:db-da})}
function advancedFlightControls(){const countries=[...new Map(aviation.flights.map(f=>{const c=flightCountry(f,'destination');return [countryKey(c),c]}).filter(([k])=>k)).entries()].sort((a,b)=>a[1].localeCompare(b[1],'pt'));const airportOptions=side=>[...new Set(aviation.flights.map(f=>f[side]).filter(Boolean))].sort().map(code=>`<option value="${esc(code)}">${esc(code)} · ${esc(aviationAirport(code)?.city||aviation.flights.find(f=>f[side]===code)?.[side+'City']||'Aeroporto')}</option>`).join('');return `<div class="flight-filter-grid"><label class="flight-search-field">BUSCAR<input id="flightSearch" type="search" placeholder="Cidade, aeroporto, companhia ou número do voo"></label><label>TIPO DE VOO<select id="flightType"><option value="">Todos os voos</option><option value="domestic">Nacionais · Brasil</option><option value="international">Internacionais</option><option value="bridge">São Paulo ↔ Rio</option></select></label><label>COMPANHIA<select id="flightCarrier"><option value="">Todas as companhias</option>${[...new Set(aviation.flights.map(f=>airlineKey(f.carrier)))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>ANO<select id="flightYear"><option value="">Todos os anos</option>${[...new Set(aviation.flights.map(f=>f.year).filter(Boolean))].sort((a,b)=>b-a).map(y=>`<option>${y}</option>`).join('')}<option value="unknown">Ano não informado</option></select></label><label>PAÍS DE DESTINO<select id="flightCountry"><option value="">Todos os países</option>${countries.map(([key,c])=>`<option value="${esc(key)}">${esc(c)}</option>`).join('')}</select></label><label>SAÍDA DE<select id="flightOrigin"><option value="">Qualquer origem</option>${airportOptions('origin')}</select></label><label>CHEGADA EM<select id="flightDestination"><option value="">Qualquer destino</option>${airportOptions('destination')}</select></label><label id="flightScopeLabel" hidden>TRAJETO INTERNACIONAL<select id="flightScope"><option value="all">Todos os internacionais</option><option value="outbound">Saindo do Brasil</option><option value="inbound">Voltando ao Brasil</option><option value="abroad">Entre outros países</option></select></label></div><div class="flight-filter-bottom"><p id="flightFilterStatus" role="status" aria-live="polite">Combine os campos para refinar sua busca.</p><label class="flight-sort-field">ORDENAR VOOS<select id="flightSort"><option value="newest">Mais recentes</option><option value="oldest">Mais antigos</option><option value="route">Origem e destino</option></select></label><button id="flightClear" type="button">Limpar filtros</button></div><div class="flight-active-filters" id="flightActiveFilters"></div>`}
function renderFlights(){renderFlightList();const fs=filteredFlightRows(),routes=new Map(),countries=new Set(),cities=new Set();let mins=0,covered=0,estimated=false;for(const f of fs){const key=f.origin+'|'+f.destination;const row=routes.get(key)||{origin:f.origin,destination:f.destination,originCity:f.originCity,destinationCity:f.destinationCity,count:0};row.count++;routes.set(key,row);const c=flightCountry(f,'destination');if(c)countries.add(countryKey(c));if(f.destinationCity)cities.add(countryKey(c)+'|'+norm(f.destinationCity));const m=aviationDuration(f);if(m!==null){mins+=m;covered++;if(!(f.minutes>0)||/estim/i.test(f.minutesKind))estimated=true}}const description=flightState.bridge?'Ponte aérea São Paulo ↔ Rio':flightState.type==='domestic'?'Voos dentro do Brasil':flightState.type==='international'?{outbound:'Voos internacionais saindo do Brasil',inbound:'Voos internacionais voltando ao Brasil',abroad:'Voos internacionais entre outros países',all:'Todos os voos internacionais'}[flightState.scope]:'Seu recorte de voos';$('#flightSummary').innerHTML=`<div class="flight-summary-heading"><span class="eyebrow">PANORAMA DO FILTRO</span><h3>${description}</h3><p>Contagem por trecho, respeitando todos os filtros selecionados.</p></div><div class="flight-summary-stats">${[[fs.length,'voos','flights'],[routes.size,'percursos','routes'],[countries.size,'países de destino','countries'],[cities.size,'cidades de destino','cities'],[covered?num(mins/60)+'h':'—',estimated?'tempo · inclui estimativas':'tempo de voo','hours']].map(([n,l,key])=>`<button data-flight-pane="${key}" aria-expanded="${flightState.pane===key}" aria-controls="flightListPanel" class="${flightState.pane===key?'is-active':''}"><strong>${n}</strong><span>${l}</span></button>`).join('')}</div><p class="flight-summary-note">Duração disponível para ${covered} de ${fs.length} voos.${flightState.type==='international'&&flightState.scope==='outbound'?' Retornos e conexões fora do Brasil estão nos outros recortes acima.':''}${flightState.type==='domestic'?' Apenas trechos com origem e destino no Brasil.':''}</p>`;renderFlightPane(fs,routes);$('#flightScopeLabel').hidden=flightState.type!=='international';syncFlightControls();document.querySelectorAll('[data-flight-kind]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.flightKind===flightState.type)))}
function renderFlightPane(fs,routes){const pane=flightState.pane;$('#flightListPanel').hidden=!pane;$('#flightCount').hidden=pane!=='flights';$('#flightGrid').hidden=pane!=='flights';$('#flightMore').parentElement.hidden=pane!=='flights';$('#flightPaneGroups').hidden=!pane||pane==='flights';$('#flightPaneHeader').hidden=!pane;if(!pane)return;const names={flights:'Voos deste recorte',routes:'Percursos deste recorte',countries:'Países de destino',cities:'Cidades de destino',hours:'Seu tempo nos céus'};$('#flightPaneHeader').innerHTML=`${flightState.cityKey?'<button id="clearCityDrill">Todas as cidades ×</button>':''}<h3>${names[pane]}</h3><button id="flightPaneClose" aria-label="Recolher detalhes">Recolher ×</button>`;if($('#clearCityDrill'))$('#clearCityDrill').onclick=()=>{flightState.cityKey='';renderFlights()};$('#flightPaneClose').onclick=()=>{flightState.pane=null;renderFlights()};if(pane==='flights')return;const target=$('#flightPaneGroups');target.className='flight-pane-groups '+(pane==='hours'?'duration-groups':'');if(pane==='routes'){target.innerHTML=[...routes.values()].sort((a,b)=>b.count-a.count||a.origin.localeCompare(b.origin)).map(r=>`<button class="explore-route-card" data-summary-origin="${esc(r.origin)}" data-summary-destination="${esc(r.destination)}"><span class="route-trace"><b>${esc(r.origin)}</b><i></i>${icon('plane')}<i></i><b>${esc(r.destination)}</b></span><span class="route-city-label">${esc(r.originCity)} → ${esc(r.destinationCity)}</span><span class="explore-card-footer"><strong>${r.count} ${r.count===1?'voo':'voos'}</strong><span>Explorar ${icon('arrow')}</span></span></button>`).join('');}else if(pane==='countries'||pane==='cities'){const groups=new Map();for(const f of fs){const c=flightCountry(f,'destination'),city=f.destinationCity;if(pane==='countries'&&!c||pane==='cities'&&!city)continue;const key=pane==='countries'?countryKey(c):countryKey(c)+'|'+norm(city);const g=groups.get(key)||{name:pane==='countries'?c:city,country:c,count:0,airports:new Set()};g.count++;if(f.destination)g.airports.add(f.destination);groups.set(key,g)}target.innerHTML=[...groups.entries()].sort((a,b)=>b[1].count-a[1].count||a[1].name.localeCompare(b[1].name,'pt')).map(([key,g])=>{const known=countries.find(c=>countryKey(c.name)===countryKey(g.country)),flag=known&&countryCodes[known.iso];return `<button class="destination-explore-card" data-summary-${pane==='countries'?'country':'city'}="${esc(key)}"><span class="destination-emblem">${pane==='countries'&&flag?`<img src="assets/flags/${flag}.svg" alt="">`:icon(pane==='countries'?'globe':'pin')}</span><strong>${esc(g.name)}</strong><small>${pane==='cities'?esc(g.country)+' · ':''}${esc([...g.airports].sort().join(' · '))}</small><span class="explore-card-footer"><strong>${g.count} ${pane==='cities'?'chegadas':g.count===1?'voo':'voos'}</strong><span>Explorar ${icon('arrow')}</span></span></button>`}).join('');}else if(pane==='hours'){const groups=new Map();let total=0,covered=0;for(const f of fs){const m=aviationDuration(f);if(m===null)continue;covered++;total+=m;const key=airlineKey(f.carrier),g=groups.get(key)||{minutes:0,count:0,estimated:false};g.minutes+=m;g.count++;g.estimated||=!(f.minutes>0)||/estim/i.test(f.minutesKind);groups.set(key,g)}target.innerHTML=`<p class="duration-caption">Tempo por companhia · duração disponível em ${covered} de ${fs.length} voos. As barras mostram a participação no tempo total deste recorte.</p>`+[...groups.entries()].sort((a,b)=>b[1].minutes-a[1].minutes).map(([name,g])=>`<article class="duration-row"><div><strong>${esc(name)}</strong><span>${Math.floor(g.minutes/60)}h ${String(g.minutes%60).padStart(2,'0')}min</span></div><div class="duration-track"><i style="width:${total?g.minutes/total*100:0}%"></i></div><small>${g.count} voos · ${total?Math.round(g.minutes/total*100):0}% do tempo${g.estimated?' · inclui estimativas':''}</small></article>`).join('');}if(!fs.length)target.innerHTML='<p class="gallery-empty">Nenhum resultado para os filtros selecionados.</p>';else if(!target.innerHTML)target.innerHTML='<p class="gallery-empty">Estes registros ainda não têm os dados necessários para esta visualização.</p>'}

function syncFlightControls(){for(const [id,key]of [['flightSearch','q'],['flightCarrier','carrier'],['flightYear','year'],['flightCountry','country'],['flightOrigin','origin'],['flightDestination','destination'],['flightSort','sort'],['flightScope','scope']])if($('#'+id).value!==flightState[key])$('#'+id).value=flightState[key];$('#flightType').value=flightState.bridge?'bridge':flightState.type;const labels={type:'Tipo',carrier:'Companhia',year:'Ano',country:'País',origin:'Saída',destination:'Chegada',scope:'Trajeto',q:'Busca',cityKey:'Cidade'},chips=[];if(flightState.bridge)chips.push(['type','São Paulo ↔ Rio']);else if(flightState.type)chips.push(['type',$('#flightType').selectedOptions[0].textContent]);for(const [id,key]of [['flightCarrier','carrier'],['flightYear','year'],['flightCountry','country'],['flightOrigin','origin'],['flightDestination','destination']])if(flightState[key])chips.push([key,$('#'+id).selectedOptions[0]?.textContent||flightState[key]]);if(flightState.type==='international'&&flightState.scope!=='all')chips.push(['scope',$('#flightScope').selectedOptions[0].textContent]);if(flightState.q)chips.push(['q',flightState.q]);if(flightState.cityKey)chips.push(['cityKey',flightState.cityKey.split('|').slice(1).join(' ')]);$('#flightActiveFilters').innerHTML=chips.map(([key,label])=>`<button type="button" data-clear-flight-filter="${key}" aria-label="Remover filtro ${esc(labels[key])}: ${esc(label)}">${esc(labels[key])}: ${esc(label)} <span aria-hidden="true">×</span></button>`).join('');$('#flightFilterStatus').textContent=chips.length?`${chips.length} ${chips.length===1?'filtro aplicado':'filtros combinados'} · ${filteredFlightRows().length} voos encontrados`:'Combine os campos para refinar sua busca.';const shortcut=flightState.bridge?'bridge':flightState.type==='international'?'international':'all';document.querySelectorAll('[data-flight-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.flightFilter===(flightState.pane==='hours'&&!chips.length?'hours':shortcut))))}
function initializeAdvancedFlights(){const host=$('.flight-filters');host.innerHTML=advancedFlightControls();host.insertAdjacentHTML('afterend','<div id="flightSummary"></div>');const panel=document.createElement('div');panel.id='flightListPanel';panel.hidden=true;$('#flightGrid').before(panel);panel.innerHTML='<div id="flightPaneHeader" class="flight-pane-header" hidden></div><div id="flightPaneGroups" hidden></div>';panel.append($('#flightGrid'),$('#flightMore').parentElement);for(const [id,key]of [['flightCountry','country'],['flightOrigin','origin'],['flightDestination','destination'],['flightSort','sort'],['flightScope','scope'],['flightCarrier','carrier'],['flightYear','year']])$('#'+id).onchange=e=>{flightState[key]=e.target.value;flightState.limit=20;renderFlights()};$('#flightSearch').oninput=e=>{flightState.q=e.target.value;flightState.limit=20;renderFlights()};$('#flightType').onchange=e=>{flightState.bridge=e.target.value==='bridge';flightState.type=flightState.bridge?'domestic':e.target.value;flightState.scope='all';flightState.limit=20;renderFlights()};document.addEventListener('click',e=>{const pane=e.target.closest('[data-flight-pane]');if(pane){flightState.pane=pane.dataset.flightPane;renderFlights();return}const clear=e.target.closest('[data-clear-flight-filter]');if(clear){const key=clear.dataset.clearFlightFilter;if(key==='type'){flightState.type='';flightState.bridge=false;flightState.scope='all'}else flightState[key]=key==='scope'?'all':'';flightState.limit=20;renderFlights();return}const dest=e.target.closest('[data-summary-country],[data-summary-city]');if(dest){if(dest.dataset.summaryCountry)flightState.country=dest.dataset.summaryCountry;else flightState.cityKey=dest.dataset.summaryCity;flightState.pane='flights';flightState.limit=20;renderFlights();return}const route=e.target.closest('[data-summary-origin]');if(route){flightState.origin=route.dataset.summaryOrigin;flightState.destination=route.dataset.summaryDestination;flightState.pane='flights';flightState.limit=20;renderFlights();$('#flightListPanel').scrollIntoView({behavior:reduced?'auto':'smooth'})}});renderFlights()}

function showFlights(key='all',scroll=true){Object.assign(flightState,{q:'',carrier:'',bridge:key==='bridge',year:'',limit:20,type:key==='international'?'international':key==='bridge'?'domestic':'',scope:'all',country:'',origin:'',destination:'',sort:'newest',listOpen:false,pane:key==='hours'?'hours':null,cityKey:''});$('#flightCollection').hidden=false;$('#flightExplore').setAttribute('aria-expanded','true');renderFlights();if(scroll)$('#flightCollection').scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'})}
function flightOnMap(id){const f=aviation.flights.find(f=>f.id===id);if(!f||!aviationHasRoute(f))return;stopPlayback();selectedTrip=null;selectedFlight=id;$('#tripSelect').value='';mapLayer='flights';document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layer===mapLayer)));update2d();update3d();const a=aviationAirport(f.origin),b=aviationAirport(f.destination);if(view==='3d'&&globe)globe.pointOfView({lat:(a.lat+b.lat)/2,lng:Math.atan2(Math.sin(a.lng*Math.PI/180)+Math.sin(b.lng*Math.PI/180),Math.cos(a.lng*Math.PI/180)+Math.cos(b.lng*Math.PI/180))*180/Math.PI,altitude:2},reduced?0:1000);else map.fitBounds([[a.lat,a.lng],[b.lat,b.lng]],{padding:[55,55],maxZoom:7});$('#mapCaption').textContent=`${f.origin} → ${f.destination} · ${f.carrier||'Meu voo'}`;$('#explore').scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'})}
function initializeFlights(){initializeAdvancedFlights();$('#flightExplore').onclick=()=>showFlights();document.querySelectorAll('[data-flight-filter]').forEach(b=>b.onclick=()=>showFlights(b.dataset.flightFilter));$('#flightClear').onclick=()=>{const pane=flightState.pane;showFlights('all',false);flightState.pane=pane;renderFlights()};$('#flightMore').onclick=()=>{flightState.limit+=20;renderFlights()};document.addEventListener('click',e=>{const b=e.target.closest('[data-flight-map]');if(b){const d=$('#atlasDetail');if(d?.open)d.close();flightOnMap(b.dataset.flightMap)}})}
function initializeNavigation(){const header=$('.preview-header'),links=[...document.querySelectorAll('.main-nav a')];const measure=()=>document.documentElement.style.setProperty('--atlas-nav-height',Math.ceil(header.getBoundingClientRect().height)+'px');new ResizeObserver(measure).observe(header);measure();const update=()=>{const top=header.getBoundingClientRect().bottom+35;let active='';for(const section of [...links.map(a=>$(a.hash))].filter(Boolean).sort((a,b)=>a.getBoundingClientRect().top-b.getBoundingClientRect().top))if(section.getBoundingClientRect().top<=top)active=section.id;links.forEach(a=>{if(a.hash==='#'+active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})};addEventListener('scroll',update,{passive:true});links.forEach(a=>a.addEventListener('click',e=>{e.preventDefault();$(a.hash)?.scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});history.replaceState(null,'',a.hash)}));update()}

function sideTrips(){return `<aside class="journey-sidebar"><span class="eyebrow">BIBLIOTECA DE VIAGENS</span><h2>Para onde vamos?</h2><label class="sidebar-search"><span class="sr-only">Buscar viagem</span><input id="tripSearch" type="search" placeholder="Buscar destino ou viagem…"></label><div class="side-trip-list">${aviation.trips.map(t=>{const fs=aviation.flights.filter(f=>t.flightIds.includes(f.id));return `<button data-trip="${esc(t.id)}">${icon('plane')}<span><strong>${esc(t.name)}</strong><small>${fs.length} trechos · ${fs[0]?.year||'Ano a confirmar'}</small></span>${icon('arrow')}</button>`}).join('')}</div></aside>`}
const galleryState={q:'',iso:'',sort:'name',limit:6};
const topicState={type:'countries',q:'',limit:40};
function stadiumPicture(v){if(v.photoUrl&&/^(https:\/\/|data:image\/(jpeg|png|webp);base64,)/i.test(v.photoUrl))return {url:v.photoUrl,credit:v.photoUrl.startsWith('data:')?'Foto pessoal':'Foto cadastrada',source:v.photoUrl.startsWith('data:')?'':v.photoUrl};const p=findStadiumDetails(v)?.photo;return p?{...p,credit:p.author+' · '+p.license}:null}
function stadiumImage(v,loading='lazy'){const p=stadiumPicture(v);const position=Number.isFinite(Number(v.photoPosition))?Math.max(0,Math.min(100,Number(v.photoPosition))):52;return p?`<img src="${esc(p.url)}" alt="${esc(v.stadium)}" loading="${loading}" decoding="async" data-fallback="${esc(p.originalUrl||'')}" style="object-position:50% ${position}%">`:'<span class="stadium-photo-empty">'+icon('stadium')+'<span>Uma história para fotografar</span></span>'}
function heroStadium(){const v=stadiums.find(v=>norm(v.stadium).includes('bernabeu'))||stadiums.find(v=>v.photoUrl&&stadiumPicture(v))||stadiums.find(v=>stadiumPicture(v));return v?`<a class="hero-stadium-teaser" href="#stadiums">${norm(v.stadium).includes('bernabeu')?'<img src="assets/memories/memoria-11.webp" alt="Santiago Bernabéu, Madrid · foto pessoal" width="900" height="675" loading="eager" fetchpriority="high">':stadiumImage(v,'eager')}<span><small>NAS MINHAS ARQUIBANCADAS</small><strong>${esc(v.stadium)}</strong><span>${esc(v.city)}${v.atlasLocality?' · '+esc(v.atlasLocality):''}</span></span>${icon('arrow')}</a>`:''}
function stadiumSection(){return `<section class="stadium-section" id="stadiums" aria-labelledby="stadiumGalleryTitle"><div class="section-title"><div><span class="eyebrow">O FUTEBOL ME LEVOU ATÉ AQUI</span><h2 id="stadiumGalleryTitle">As arquibancadas da minha história.</h2><p>Fotos, jogos e lembranças dos estádios que conheci.</p></div><button class="manager-section-button" data-manage="stadiums">Gerenciar coleção ${icon('arrow')}</button></div><div class="stadium-filters"><label>BUSCAR ESTÁDIO OU CIDADE<input id="stadiumSearch" type="search" placeholder="Ex.: Azteca, Santos, Buenos Aires…"></label><label>PAÍS<select id="stadiumCountry"><option value="">Todos os países</option>${countries.filter(c=>stadiums.some(v=>v.iso===c.iso)).map(c=>`<option value="${c.iso}">${esc(c.name)}</option>`).join('')}</select></label><label>ORDENAR<select id="stadiumSort"><option value="name">Nome · A–Z</option><option value="country">País</option><option value="visits">Mais visitados</option></select></label><button id="stadiumClear">Limpar filtros</button></div><p id="stadiumCount" class="stadium-count" role="status" aria-live="polite"></p><div class="stadium-gallery" id="stadiumGallery"></div><div class="stadium-more"><button class="outline-button" id="stadiumMore">Ver mais estádios ${icon('arrow')}</button><span id="stadiumShown"></span></div></section>`}
function filteredStadiums(){return visits.map((v,index)=>({...v,index})).filter(v=>v.stadium&&(!galleryState.iso||v.iso===galleryState.iso)&&norm([v.stadium,v.city,v.atlasLocality,v.country,v.club].join(' ')).includes(norm(galleryState.q))).sort((a,b)=>galleryState.sort==='country'?a.country.localeCompare(b.country,'pt')||a.stadium.localeCompare(b.stadium,'pt'):galleryState.sort==='visits'?(Math.max(1,Number(b.visitCount)||1)-Math.max(1,Number(a.visitCount)||1))||a.stadium.localeCompare(b.stadium,'pt'):a.stadium.localeCompare(b.stadium,'pt'))}
function renderGallery(){const fs=filteredStadiums(),shown=fs.slice(0,galleryState.limit);$('#stadiumCount').textContent=fs.length+' '+(fs.length===1?'estádio encontrado':'estádios encontrados');$('#stadiumGallery').innerHTML=shown.length?shown.map(v=>{const p=stadiumPicture(v);return `<article class="stadium-gallery-card"><button class="stadium-card-image" data-stadium="${v.index}" aria-label="Ver fotos e detalhes de ${esc(v.stadium)}">${stadiumImage(v)}<span class="stadium-country">${esc(v.country)}</span><span class="stadium-image-cta">Ver detalhes ${icon('arrow')}</span><span class="image-unavailable" hidden>Fotografia indisponível no momento</span></button><div class="stadium-card-body"><h3><button data-stadium="${v.index}">${esc(v.stadium)}</button></h3><p>${esc(v.city)}${v.atlasLocality?' · '+esc(v.atlasLocality):''} · ${Math.max(1,Number(v.visitCount)||1)} ${Number(v.visitCount)>1?'visitas':'visita'}</p>${p?.source?`<a class="photo-credit" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Foto: ${esc(p.credit)} ↗</a>`:`<span class="photo-credit">${esc(p?.credit||'Sua coleção de memórias')}</span>`}</div></article>`}).join(''):'<p class="gallery-empty">Nenhum estádio encontrado. Tente outro nome ou limpe os filtros.</p>';$('#stadiumShown').textContent=fs.length?'Mostrando '+shown.length+' de '+fs.length+' estádios':'';$('#stadiumMore').hidden=shown.length>=fs.length;bindImageFallbacks($('#stadiumGallery'))}
function bindImageFallbacks(root){root.querySelectorAll('img').forEach(img=>img.addEventListener('error',()=>{const fallback=img.dataset.fallback;if(fallback&&img.src!==fallback){img.dataset.fallback='';img.src=fallback;return}img.hidden=true;const label=img.parentElement.querySelector('.image-unavailable');if(label)label.hidden=false}))}
function dialogShell(){let d=$('#atlasDetail');if(!d){d=document.createElement('dialog');d.id='atlasDetail';d.className='atlas-detail';d.setAttribute('aria-labelledby','atlasDetailTitle');d.innerHTML='<button class="atlas-detail-close" aria-label="Fechar detalhes">×</button><div id="atlasDetailBody"></div>';document.body.append(d);d.querySelector('.atlas-detail-close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})}return d}
function openStadium(index){const v=visits[index];if(!v?.stadium)return;const d=dialogShell(),p=stadiumPicture(v),games=Array.isArray(v.matches)?v.matches.filter(g=>g&&typeof g==='object'):[];$('#atlasDetailBody').innerHTML=`<div class="stadium-detail-photo">${stadiumImage(v,'eager')}<span class="image-unavailable" hidden>Fotografia indisponível no momento</span></div><div class="stadium-detail-body"><span class="eyebrow">${esc(v.country)} · ESTÁDIO VISITADO</span><h2 id="atlasDetailTitle">${esc(v.stadium)}</h2><p class="detail-subtitle">${esc(v.city)}${v.atlasLocality?' · '+esc(v.atlasLocality):''} · ${Math.max(1,Number(v.visitCount)||1)} ${Number(v.visitCount)>1?'visitas':'visita'}</p><div class="stadium-detail-facts">${v.club?`<div><small>CLUBE / EVENTO</small><strong>${esc(v.club)}</strong></div>`:''}${v.date?`<div><small>DATA DA VISITA</small><strong>${esc(v.date)}</strong></div>`:''}<div><small>JOGOS REGISTRADOS</small><strong>${games.length}</strong></div></div>${v.notes?`<div class="detail-notes"><h3>Minha lembrança</h3><p>${esc(v.notes)}</p></div>`:''}${games.length?`<details class="stadium-games"><summary>Meus jogos neste estádio (${games.length})</summary>${games.map(g=>`<article><strong>${esc(g.homeTeam||'Mandante')} ${esc(g.homeScore??'—')} × ${esc(g.awayScore??'—')} ${esc(g.awayTeam||'Visitante')}</strong><p>${esc(g.date||'Data não informada')} · ${esc(g.competition||'')}</p>${g.notes?`<p>${esc(g.notes)}</p>`:''}</article>`).join('')}</details>`:''}${p?.source?`<a class="photo-credit" href="${esc(p.source)}" target="_blank" rel="noopener noreferrer">Foto: ${esc(p.credit)} ↗</a>`:`<p class="photo-credit">${esc(p?.credit||'')}</p>`}${p?.licenseUrl?`<a class="photo-credit" href="${esc(p.licenseUrl)}" target="_blank" rel="noopener noreferrer">Licença: ${esc(p.license)}</a>`:''}<div class="detail-actions"><button class="gold-button" id="detailMap">Localizar no mapa ${icon('pin')}</button><button class="outline-button" data-edit-visit="${index}">Editar estádio ${icon('arrow')}</button></div></div>`;$('#detailMap').onclick=()=>{d.close();const p=points.find(p=>p.index===index);if(!p){$('#mapCaption').textContent='Este estádio ainda não tem coordenadas cadastradas.';$('#explore').scrollIntoView({behavior:reduced?'auto':'smooth'});return}mapLayer='stadiums';document.querySelectorAll('[data-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layer===mapLayer)));update2d();update3d();if(view==='3d'&&globe)globe.pointOfView({lat:p.lat,lng:p.lng,altitude:.9},reduced?0:1000);else map.setView([p.lat,p.lng],12);$('#explore').scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});place(p)};bindImageFallbacks($('#atlasDetailBody'));if(!d.open)d.showModal()}
function openTopic(type,query=''){if(type==='flights'){showFlights();return}if(type==='stadiums'){$('#stadiums').scrollIntoView({behavior:reduced?'auto':'smooth'});return}topicState.type=type;topicState.q=query;topicState.limit=40;const names={countries:'Países visitados',cities:'Cidades exploradas',flights:'Meu histórico de voos'};const d=dialogShell();$('#atlasDetailBody').innerHTML=`<div class="topic-detail"><span class="eyebrow">MINHA HISTÓRIA EM DETALHES</span><h2 id="atlasDetailTitle">${names[type]||'Meu Atlas'}</h2>${type==='cities'?'<div class="manager-section-actions"><button class="outline-button" data-manager-new="city">＋ Incluir cidade</button><button class="outline-button" data-manage="cities">Gerenciar cidades</button></div>':''}<label class="topic-search"><span class="sr-only">Buscar neste tópico</span><input id="topicSearch" type="search" placeholder="${type==='flights'?'Buscar rota, companhia, voo ou ano…':'Buscar cidade ou país…'}" value="${esc(query)}"></label><p id="topicCount" role="status" aria-live="polite"></p><div id="topicRows"></div><button class="outline-button" id="topicMore">Carregar mais</button>${type==='flights'?'<a class="topic-edit" href="#journeys">Explorar registros de voos</a>':''}</div>`;$('#topicSearch').oninput=e=>{topicState.q=e.target.value;topicState.limit=40;renderTopic()};$('#topicMore').onclick=()=>{topicState.limit+=40;renderTopic()};renderTopic();if(!d.open)d.showModal()}
function renderTopic(){const q=norm(topicState.q);let rows=[];if(topicState.type==='countries')rows=countries.map(c=>({...c,rows:visits.filter(v=>v.iso===c.iso)})).filter(c=>norm(c.name).includes(q)).map(c=>`<button class="topic-country" data-topic-country="${c.iso}">${countryCodes[c.iso]?`<img src="assets/flags/${countryCodes[c.iso]}.svg" alt="" width="34" height="25">`:icon('globe')}<span><strong>${esc(c.name)}</strong><small>${new Set(c.rows.map(v=>norm(v.city))).size} cidades · ${c.rows.filter(v=>v.stadium).length} estádios</small></span>${icon('arrow')}</button>`);else if(topicState.type==='cities')rows=[...new Map(visits.map(v=>[v.iso+'|'+norm(v.city),v])).values()].sort((a,b)=>a.city.localeCompare(b.city,'pt')).filter(v=>norm(v.city+' '+v.country).includes(q)).map(v=>`<button class="topic-country" data-topic-country="${esc(v.iso)}">${icon('pin')}<span><strong>${esc(v.city)}${v.atlasLocality?' · '+esc(v.atlasLocality):''}</strong><small>${esc(v.country)} · ${stadiums.filter(s=>s.iso===v.iso&&norm(s.city)===norm(v.city)).length} estádios</small></span>${icon('arrow')}</button>`);else rows=aviation.flights.filter(f=>norm([f.origin,f.destination,f.originCity,f.destinationCity,f.code,f.carrier,f.dayMonth,f.year].join(' ')).includes(q)).map(f=>`<button class="topic-flight" data-flight-detail="${esc(f.id)}"><span><strong>${esc(f.origin||f.originCity)} → ${esc(f.destination||f.destinationCity)}</strong><small>${esc(f.originCity)} → ${esc(f.destinationCity)}</small></span><span>${esc(f.carrier||'Companhia não informada')}<small>${esc(f.dayMonth)} ${f.year||'Ano não informado'}</small></span>${icon('arrow')}</button>`);$('#topicCount').textContent=rows.length+' '+(topicState.type==='flights'?'registros':topicState.type==='cities'?'cidades':'países');$('#topicRows').innerHTML=rows.slice(0,topicState.limit).join('')||'<p>Nenhum resultado para esta busca.</p>';$('#topicMore').hidden=rows.length<=topicState.limit}
function openFlight(id){const f=aviation.flights.find(f=>f.id===id);if(!f)return;const d=dialogShell();$('#atlasDetailBody').innerHTML=`<div class="topic-detail"><button class="topic-back" id="backFlights">← Voltar aos voos</button><button class="outline-button manager-detail-edit" data-edit-flight="${esc(f.id)}">Editar voo</button><span class="eyebrow">UM TRECHO DA MINHA HISTÓRIA</span><h2 id="atlasDetailTitle">${esc(f.origin||f.originCity)} → ${esc(f.destination||f.destinationCity)}</h2><p>${esc(f.originCity)} → ${esc(f.destinationCity)}</p><div class="stadium-detail-facts">${[['COMPANHIA',f.carrier||'Não informada'],['VOO',f.code||'Não informado'],['DATA',flightDate(f)],['DISTÂNCIA DIRETA',f.km?num(f.km)+' km':'Não calculada']].map(([k,v])=>`<div><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div>${f.notes?`<details class="stadium-games"><summary>Notas deste registro</summary><p>${esc(f.notes)}</p></details>`:''}</div>`;$('#backFlights').onclick=()=>{d.close();$('#flightCollection').hidden=false;renderFlights();$('#flightCollection').scrollIntoView({behavior:reduced?'auto':'smooth'})};$('#atlasDetailBody .topic-detail').insertAdjacentHTML('beforeend',`<p class="detail-subtitle">${esc(durationLabel(f))}</p>${aviationHasRoute(f)?`<button class="gold-button" data-flight-map="${esc(f.id)}">Ver rota no mapa ${icon('pin')}</button>`:''}`);if(!d.open)d.showModal()}
function initializeCollections(){renderGallery();bindImageFallbacks($('.immersive-intro'));$('#stadiumSearch').oninput=e=>{galleryState.q=e.target.value;galleryState.limit=6;renderGallery()};$('#stadiumCountry').onchange=e=>{galleryState.iso=e.target.value;galleryState.limit=6;renderGallery()};$('#stadiumSort').onchange=e=>{galleryState.sort=e.target.value;renderGallery()};$('#stadiumClear').onclick=()=>{Object.assign(galleryState,{q:'',iso:'',sort:'name',limit:6});$('#stadiumSearch').value='';$('#stadiumCountry').value='';$('#stadiumSort').value='name';renderGallery()};$('#stadiumMore').onclick=()=>{galleryState.limit+=12;renderGallery()};const versions=document.querySelector('.review-bar nav');if(versions){versions.setAttribute('aria-label','Versões da opção 01');versions.innerHTML='<a href="conceito-1-v1.html">V1</a><a href="atlas-01-v2.html" aria-current="page">V2</a>'}document.addEventListener('click',e=>{const topic=e.target.closest('[data-topic]');if(topic){e.preventDefault();openTopic(topic.dataset.topic)}const stadium=e.target.closest('[data-stadium]');if(stadium)openStadium(Number(stadium.dataset.stadium));const countryStadium=e.target.closest('[data-country-stadium]');if(countryStadium){const index=Number(countryStadium.dataset.countryStadium),p=points.find(p=>p.index===index);if(p){if(view==='3d'&&globe)globe.pointOfView({lat:p.lat,lng:p.lng,altitude:.65},reduced?0:900);else map.setView([p.lat,p.lng],13);place(p)}else openStadium(index)}const country=e.target.closest('[data-topic-country]');if(country){$('#atlasDetail').close();focusCountry(country.dataset.topicCountry)}const flight=e.target.closest('[data-flight-detail]');if(flight)openFlight(flight.dataset.flightDetail)})}
function initializeRails(){let paused=reduced;const tracks=[...document.querySelectorAll('.auto-rail')].map(el=>({el,hover:false,focus:false,drag:false,moved:false,direction:1,resumeAt:0}));const control=$('#railMotion');const label=()=>{control.textContent=paused?'Ativar movimento':'Pausar movimento';control.setAttribute('aria-pressed',String(paused))};label();control.onclick=()=>{paused=!paused;label()};for(const t of tracks){const el=t.el;el.addEventListener('mouseenter',()=>t.hover=true);el.addEventListener('mouseleave',()=>t.hover=false);el.addEventListener('focusin',()=>t.focus=true);el.addEventListener('focusout',e=>{if(!el.contains(e.relatedTarget))t.focus=false});el.addEventListener('pointerdown',e=>{t.resumeAt=performance.now()+3500;if(e.pointerType!=='mouse'||e.button!==0)return;t.drag=true;t.moved=false;t.x=e.clientX;t.scroll=el.scrollLeft});el.addEventListener('pointermove',e=>{if(!t.drag)return;const dx=e.clientX-t.x;if(Math.abs(dx)>4){t.moved=true;el.classList.add('dragging');if(!el.hasPointerCapture(e.pointerId))el.setPointerCapture(e.pointerId);el.scrollLeft=t.scroll-dx;e.preventDefault()}});const finish=e=>{if(!t.drag)return;t.drag=false;el.classList.remove('dragging');if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId);t.resumeAt=performance.now()+3500;setTimeout(()=>t.moved=false,100)};el.addEventListener('pointerup',finish);el.addEventListener('pointercancel',finish);el.addEventListener('click',e=>{if(t.moved){e.preventDefault();e.stopPropagation()}},true);el.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();el.scrollLeft+=(e.key==='ArrowRight'?1:-1)*110;t.resumeAt=performance.now()+3500}})}let previous=performance.now();function tick(now){const dt=Math.min(50,now-previous);previous=now;for(const t of tracks){if(paused||document.hidden||t.hover||t.focus||t.drag||now<t.resumeAt){t.position=t.el.scrollLeft;continue}const max=t.el.scrollWidth-t.el.clientWidth;if(max<1)continue;t.position=Math.max(0,Math.min(max,(t.position??t.el.scrollLeft)+t.direction*dt*.025));t.el.scrollLeft=t.position;if(t.position>=max-1)t.direction=-1;else if(t.position<=0)t.direction=1}requestAnimationFrame(tick)}requestAnimationFrame(tick)}

let content='';
if(layout===1)content=`<main id="main"><div class="immersive-shell"><section class="immersive-intro"><span class="eyebrow">FUTEBOL É O DESTINO. A VIAGEM FAZ PARTE.</span><h1>Viagens.<br>Futebol.<br><em>Histórias.</em></h1><p>Cada estádio, um capítulo. Cada viagem, uma história que começa muito antes do apito inicial.</p><a class="gold-button" href="#stadiums">Explorar meus estádios ${icon('arrow')}</a>${heroStadium()}<div class="intro-coordinate"><i></i> SÃO PAULO · MEU PONTO DE PARTIDA</div></section>${mapMarkup}</div>${stats()}${stadiumSection()}${passport()}${recent()}${memories()}</main>`;
if(layout===2)content=`<main id="main"><section class="editorial-hero"><img class="editorial-backdrop" src="assets/editorial/istanbul.webp" alt="Panorama de Istambul e do Bósforo" width="1920" height="1440"><div class="editorial-copy"><span class="eyebrow">VIAGENS, FUTEBOL E TUDO ENTRE ELES</span><h1>Alguns lugares<br>mudam a nossa<br><em>história.</em></h1><p>Meu Atlas é sobre esses encontros.<br>Com o mundo. Com o jogo. Com a vida.</p><a class="gold-button" href="#explore">Explorar minhas memórias ${icon('arrow')}</a></div><div class="editorial-destination"><span>EM DESTAQUE</span><strong>Istambul, Turquia</strong>${credit('istanbul')}</div><span class="hero-index">01 <i></i> DIÁRIO DE BORDO</span></section>${passport()}${stats()}${memories()}${mapMarkup}${recent()}</main>`;
if(layout===3)content=`<main id="main"><section class="dashboard-heading"><div><span class="eyebrow">MEU ATLAS PESSOAL</span><h1>Seu mundo,<br><em>por outro ângulo.</em></h1></div><p>Cidades que conheci. Caminhos que percorri.<br>Histórias que quero guardar.</p><a class="outline-button" href="#main">Abrir meu Atlas ${icon('arrow')}</a></section>${stats()}<div class="dashboard-layout">${sideTrips()}${mapMarkup}</div>${passport()}${recent()}${memories()}</main>`;
$('#previewApp').innerHTML=nav+(demo?'<p class="data-mode is-demo">Dados demonstrativos. Use Gerenciar meu Atlas para começar ou <button class="manager-inline-link" data-manager-import>importe seu backup</button> neste navegador.</p>':'')+content+`<footer class="preview-footer"><a class="wordmark" href="#main">${icon('globe')} Meu Atlas</a><span>Uma coleção de destinos. Uma vida de histórias.</span><details><summary>Créditos de imagens e bibliotecas</summary><p>Fotografias ilustrativas de destinos, disponibilizadas no Wikimedia Commons. Não são apresentadas como fotos pessoais.</p>${Object.entries(photoCredits).map(([id,c])=>`<a href="${c.source}" target="_blank" rel="noopener noreferrer">${id}: ${esc(c.author)} · ${c.license} ↗</a>`).join('')}<p>Globe.gl: MIT · Bandeiras: flag-icons, MIT · Ícones de marcas: Simple Icons, CC0. Marcas pertencem aos seus titulares.</p><a href="DESIGN-CREDITS.md">Fontes e licenças completas ↗</a><a href="COMPETITION-LOGOS.md">Fontes dos logotipos das competições ↗</a></details><button class="manager-inline-link" data-manager-import>Importar / restaurar backup ${icon('arrow')}</button></footer>`;
let map,globe,geo=null,leafletLayer,selectedTrip='',view='2d',playing=false,animationFrame=0,playStarted=0,playLeg=0,flightMarker,globeLoading=null,isVisible=true,manualView=false,viewRequest=0,mapLayer='all';
const points=visits.map((v,index)=>{if(validFlightCoordinates(v.lat,v.lng))return {...v,index,lat:Number(v.lat),lng:Number(v.lng),type:'visit'};if(v.stadium)return null;const ref=flightCityIndex.get(v.iso+'|'+normalizeFlightCity(v.atlasLocality||v.city));return ref?{...v,index,lat:ref.lat,lng:ref.lng,type:'visit'}:null}).filter(Boolean);
const missingStadiumPoints=visits.map((v,index)=>({...v,index})).filter(v=>v.stadium&&!points.some(p=>p.index===v.index));
const mapAudit=document.createElement('details');mapAudit.className='stadium-map-audit';mapAudit.innerHTML=`<summary>Estádios no mapa: ${stadiums.length-missingStadiumPoints.length} de ${stadiums.length}${missingStadiumPoints.length?' · conferir localizações':''}</summary><p>${missingStadiumPoints.length?'Faltam coordenadas válidas para estes registros:':'Todos os estádios cadastrados neste navegador têm coordenadas válidas para o mapa.'}</p>${missingStadiumPoints.map(v=>`<button data-stadium="${v.index}">${esc(v.stadium)} · ${esc(v.city)}${v.atlasLocality?' · '+esc(v.atlasLocality):''}</button>`).join('')}`;$('#explore').append(mapAudit);
function currentFlights(){if(selectedFlight)return aviation.flights.filter(f=>f.id===selectedFlight);const t=aviation.trips.find(t=>t.id===selectedTrip);return t?aviation.flights.filter(f=>t.flightIds.includes(f.id)).sort((a,b)=>t.flightIds.indexOf(a.id)-t.flightIds.indexOf(b.id)):routeFlights}
function routes(){if(mapLayer==='stadiums')return [];const unique=new Map();for(const f of currentFlights().filter(aviationHasRoute)){const a=aviationAirport(f.origin),b=aviationAirport(f.destination),key=selectedTrip?f.origin+'|'+f.destination:[f.origin,f.destination].sort().join('|');if(!unique.has(key))unique.set(key,{startLat:a.lat,startLng:a.lng,endLat:b.lat,endLng:b.lng,f,color:selectedTrip||selectedFlight?'#f2bd30':'rgba(211,227,238,0.65)'});}return [...unique.values()]}
function allPoints(){const codes=mapLayer==='stadiums'?[]:[...new Set(currentFlights().filter(aviationHasRoute).flatMap(f=>[f.origin,f.destination]))];return [...codes.map(code=>({...aviationAirport(code),type:'airport',code})),...(mapLayer==='flights'?[]:points.filter(p=>!p.stadium)),...(mapLayer==='flights'?[]:points.filter(p=>p.stadium))]}
function place(p){$('#mapPlace').hidden=false;$('#placeKind').textContent=p.stadium?'ESTÁDIO VISITADO':p.type==='airport'?'AEROPORTO':'CIDADE VISITADA';$('#placeTitle').textContent=p.stadium||p.city;$('#placeDescription').textContent=(p.code?p.code+' · ':'')+(p.country||'');$('#placeExplore').innerHTML=(p.stadium?'Ver estádio':p.type==='airport'?'Ver voos':'Explorar cidade')+' '+icon('arrow');$('#placeExplore').onclick=()=>p.stadium?openStadium(p.index):openTopic(p.type==='airport'?'flights':'cities',p.type==='airport'?p.code:p.city)}
function mapStyle(f){const visited=countries.some(c=>c.iso===(f.properties['ISO3166-1-Alpha-3']||f.properties.ISO_A3));return {color:visited?'#b99940':'#82909a',weight:visited?1.2:.55,fillColor:visited?'#d4c79d':'#c3cbd0',fillOpacity:1}}
function update2d(){if(!map)return;leafletLayer.clearLayers();if(geo)L.geoJSON(geo,{style:mapStyle,interactive:false,smoothFactor:1.6}).addTo(leafletLayer);for(const r of routes())L.polyline(aviationArc(aviationAirport(r.f.origin),aviationAirport(r.f.destination)),{color:selectedTrip?'#866817':'#526b7a',weight:selectedTrip?3:1.3,opacity:selectedTrip?.9:.45,interactive:false}).addTo(leafletLayer);for(const p of allPoints())L.circleMarker([p.lat,p.lng],{radius:p.stadium?6:p.type==='airport'?4:4.5,weight:1.8,color:p.stadium?'#fff':'#fff',fillColor:p.stadium?'#c7971e':p.type==='airport'?'#314c60':'#647d8c',fillOpacity:1,bubblingMouseEvents:false}).bindTooltip(esc(p.stadium||p.city)).on('click',()=>place(p)).addTo(leafletLayer)}
function make2d(){if(map)return;map=L.map('previewMap2d',{zoomControl:false,worldCopyJump:false,maxBounds:[[-85,-180],[85,180]],maxBoundsViscosity:1,scrollWheelZoom:false,minZoom:0,zoomSnap:.25,maxZoom:13,preferCanvas:true}).setView([14,-20],2);L.control.zoom({position:'bottomright'}).addTo(map);L.control.attribution({prefix:false}).addAttribution('Natural Earth / geo-countries').addTo(map);leafletLayer=L.layerGroup().addTo(map);map.fitBounds([[-60,-180],[82,180]],{padding:[12,12],animate:false});update2d();requestAnimationFrame(()=>{if(view==='2d')map.invalidateSize({pan:false})})}
function update3d(){if(!globe)return;globe.pointsData(allPoints()).arcsData(routes());globe.polygonsData([]);}
